5	/**
6	 * Business rule: on creation an owner is assigned a {@code customerCode} formatted
7	 * {@code <LAST3>-<NNNN>}, where LAST3 is the upper-cased first three letters of the last name
8	 * and NNNN is a global 4-digit zero-padded sequence equal to one more than the current number
9	 * of owners (e.g. {@code SMI-0007}). Kept as a small, self-contained unit so the rule can be
10	 * applied from the create flow without adding complexity to the controller or service.
11	 */
12	public final class OwnerCustomerCodePolicy {
13	
14	    private OwnerCustomerCodePolicy() {
15	    }
16	
17	    /**
18	     * Assign the {@code customerCode} for a newly created owner.
19	     *
20	     * @param clinicService source of the current owner count
21	     * @param owner         the owner being created
22	     */
23	    public static void assignCustomerCode(ClinicService clinicService, Owner owner) {
24	        String lastName = owner.getLastName();
25	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
26	        int sequence = clinicService.findAllOwners().size() + 1;
27	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
28	    }
29	}
