5	/**
6	 * Business rule: an owner's {@code membershipTier} is {@code SILVER} when it has no namesakes
7	 * (namesakeCount is 0) and an email is present, and {@code BRONZE} otherwise. Kept as a small,
8	 * self-contained unit so the rule can be applied from the read flow without adding complexity to
9	 * the mapper, controller, or service.
10	 */
11	public final class OwnerMembershipTierPolicy {
12	
13	    private OwnerMembershipTierPolicy() {
14	    }
15	
16	    /**
17	     * Derive the {@code membershipTier} for the given owner.
18	     *
19	     * @param owner the owner whose membership tier to derive
20	     * @return {@code "SILVER"} when the owner has no namesakes and an email, otherwise {@code "BRONZE"}
21	     */
22	    public static String membershipTier(Owner owner) {
23	        Integer namesakeCount = owner.getNamesakeCount();
24	        boolean silver = namesakeCount != null && namesakeCount == 0
25	            && owner.getEmail() != null && !owner.getEmail().isEmpty();
26	        return silver ? "SILVER" : "BRONZE";
27	    }
28	}
