11	/**
12	 * Business rule: two owners must not share a household by accident. On creation an owner is
13	 * rejected when another owner already has the same last name and address, compared
14	 * case-insensitively after collapsing runs of whitespace. The caller may opt in to sharing a
15	 * household ({@code sharesHousehold == true}), which skips the check. Kept as a small,
16	 * self-contained unit so the rule can be enforced from the create flow without adding
17	 * complexity to the controller or service.
18	 */
19	public final class OwnerHouseholdPolicy {
20	
21	    private OwnerHouseholdPolicy() {
22	    }
23	
24	    /**
25	     * Reject the given owner if another existing owner has the same last name and address,
26	     * unless the request explicitly opted in to sharing a household.
27	     *
28	     * @param clinicService   source of the existing owners
29	     * @param owner           the owner being created
30	     * @param sharesHousehold whether the request opted in to a shared household
31	     * @throws DuplicateHouseholdException if the household already exists and sharing was not opted in
32	     */
33	    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
34	        String lastName = normalize(owner.getLastName());
35	        String address = normalize(owner.getAddress());
36	        for (Owner existing : clinicService.findAllOwners()) {
37	            if (!existing.getId().equals(owner.getId())
38	                && lastName.equals(normalize(existing.getLastName()))
39	                && address.equals(normalize(existing.getAddress()))) {
40	                if (!Boolean.TRUE.equals(sharesHousehold)) {
41	                    throw new DuplicateHouseholdException();
42	                }
43	                owner.setHouseholdId(householdId(lastName, address));
44	                return;
45	            }
46	        }
47	    }
48	
49	    private static String normalize(String value) {
50	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
51	    }
52	
53	    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
54	    private static String householdId(String lastName, String address) {
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder();
59	            for (int i = 0; i < 8; i++) {
60	                sb.append(String.format("%02x", digest[i]));
61	            }
62	            return sb.toString();
63	        }
64	        catch (NoSuchAlgorithmException e) {
65	            throw new IllegalStateException(e);
66	        }
67	    }
68	
69	    /** Thrown when another owner already shares the same last name and address. */
70	    @ResponseStatus(HttpStatus.CONFLICT)
71	    public static class DuplicateHouseholdException extends RuntimeException {
72	    }
73	}
